  "cache": [
    {
      "name": "build.test",
      "type": "A",
      "status": "NODATA",
      "stored_at": 0,
      "ttl": 60,
      "value": null
    }
  ],
  "query": {
    "name": "build.test",
    "type": "A",
    "time": 40
  },
  "authoritative": {
    "build.test/A": {
      "status": "NOERROR",
      "value": "192.0.2.20",
      "ttl": 120
    }
  }
}

